package com.campusradar.social;

import com.campusradar.common.*;
import com.campusradar.security.CurrentUser;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static com.campusradar.common.SqlRows.map;

@RestController
@RequestMapping("/api/v1")
public class SocialController {
    private final SocialService service;private final CurrentUser auth;private final OwnerTransactions tx;private final ContractInputs inputs;
    public SocialController(SocialService service,CurrentUser auth,OwnerTransactions tx,ContractInputs inputs){this.service=service;this.auth=auth;this.tx=tx;this.inputs=inputs;}
    private String optional(HttpServletRequest r){try{return auth.requireId(r);}catch(ApiProblem e){if(e.status()==401)return null;throw e;}}
    private ResponseEntity<?> write(String user,String method,String route,String key,Map<String,Object>b,String schema,int status,Supplier<Object>action){if(schema!=null)inputs.validate(schema,b);return ApiSupport.response(tx.write(user,method,route,key,b,status,false,action),status);}
    private ResponseEntity<?> page(String select,String from,Map<String,Object>p,int page,int size,Set<String>json,Set<String>bool){SocialService.page(page,size);long total=service.sql.db.queryForObject("SELECT COUNT(*) "+from,p,Long.class);p.put("limit",size);p.put("offset",(page-1)*size);return ApiSupport.page(service.sql.query("SELECT "+select+" "+from+" ORDER BY created_at DESC,id LIMIT :limit OFFSET :offset",p,json,bool),page,size,total);}
    @GetMapping({"/posts","/me/posts"})public ResponseEntity<?> posts(HttpServletRequest r,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){String user=r.getRequestURI().contains("/me/")?auth.requireId(r):optional(r);boolean own=r.getRequestURI().contains("/me/");SocialService.page(page,size);var p=map("u",user,"limit",size,"offset",(page-1)*size);String where=own?"p.author_id=:u":"p.status='PUBLISHED'";long total=service.sql.db.queryForObject("SELECT COUNT(*) FROM posts p WHERE "+where,p,Long.class);var rows=service.sql.query("SELECT "+SocialService.POST+" FROM posts p WHERE "+where+" ORDER BY p.created_at DESC,p.id LIMIT :limit OFFSET :offset",p,Set.of("tags"),Set.of());rows.forEach(row->service.postCounts(user,row));return ApiSupport.page(rows,page,size,total);}
    @PostMapping("/posts")public ResponseEntity<?> createPost(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/posts",key,b,"PostInput",201,()->service.createPost(u,b));}
    @PatchMapping("/posts/{id}")public ResponseEntity<?> patchPost(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"PATCH","/posts/"+id,null,b,"PostPatch",200,()->service.patchPost(u,id,b));}
    @DeleteMapping("/posts/{id}")public ResponseEntity<?> deletePost(HttpServletRequest r,@PathVariable String id,@RequestParam int version){String u=auth.requireId(r);return write(u,"DELETE","/posts/"+id,null,map("version",version),"VersionInput",204,()->service.deletePost(u,id,version));}
    @PutMapping("/posts/{id}/like")public ResponseEntity<?> like(HttpServletRequest r,@PathVariable String id){String u=auth.requireId(r);return write(u,"PUT","/posts/"+id+"/like",null,Map.of(),null,200,()->{service.like(u,id,true);return map("accepted",true);});}
    @DeleteMapping("/posts/{id}/like")public ResponseEntity<?> unlike(HttpServletRequest r,@PathVariable String id){String u=auth.requireId(r);return write(u,"DELETE","/posts/"+id+"/like",null,Map.of(),null,204,()->service.like(u,id,false));}
    @GetMapping({"/posts/{id}/comments","/experiences/{id}/comments"})public ResponseEntity<?> comments(HttpServletRequest r,@PathVariable String id,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){String type=r.getRequestURI().contains("/posts/")?"posts":"experiences";service.publishedTopic(type,id);return page(SocialService.COMMENT,"FROM comments WHERE "+service.topic(type)+"=:id AND status='PUBLISHED'",map("id",id),page,size,Set.of(),Set.of());}
    @PostMapping({"/posts/{id}/comments","/experiences/{id}/comments"})public ResponseEntity<?> comment(HttpServletRequest r,@PathVariable String id,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){
        String u=auth.requireId(r),type=r.getRequestURI().contains("/posts/")?"posts":"experiences";inputs.validate("CommentInput",b);
        Object result=tx.write(u,"POST","/"+type+"/"+id+"/comments",key,b,201,false,()->service.comment(u,type,id,b));
        // Old servers cached PENDING creation DTOs. Reconcile that legacy snapshot with
        // the author's existing row after the explicit publication-policy migration.
        // Never create or publish a second row just to repair the response.
        if(result instanceof Map<?,?> cached && "PENDING".equals(cached.get("status")) && cached.get("id") instanceof String commentId)result=service.ownComment(u,type,id,commentId);
        return ApiSupport.response(result,201);
    }
    @DeleteMapping("/me/comments/{commentId}")public ResponseEntity<?> withdrawComment(HttpServletRequest r,@PathVariable String commentId,@RequestParam int version){String u=auth.requireId(r);return write(u,"DELETE","/me/comments/"+commentId,null,map("version",version),"VersionInput",204,()->service.withdrawComment(u,commentId,version));}
    @DeleteMapping({"/posts/{id}/comments/{commentId}","/experiences/{id}/comments/{commentId}"})public ResponseEntity<?> deleteComment(HttpServletRequest r,@PathVariable String id,@PathVariable String commentId,@RequestParam int version){String u=auth.requireId(r),type=r.getRequestURI().contains("/posts/")?"posts":"experiences";return write(u,"DELETE",r.getRequestURI(),null,map("version",version),"VersionInput",204,()->service.deleteComment(u,type,id,commentId,version));}
    @PostMapping("/reports")public ResponseEntity<?> report(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/reports",key,b,"ReportInput",201,()->service.report(u,b));}
    @GetMapping("/buddy/rooms")public ResponseEntity<?> rooms(HttpServletRequest r,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="false")boolean mine){String u=auth.requireId(r);SocialService.page(page,size);var p=map("u",u,"limit",size,"offset",(page-1)*size);String where=mine?"EXISTS(SELECT 1 FROM buddy_members m WHERE m.room_id=r.id AND m.user_id=:u)":"r.visibility='PUBLIC' AND r.state='OPEN'";long total=service.sql.db.queryForObject("SELECT COUNT(*) FROM buddy_rooms r WHERE "+where,p,Long.class);var rows=service.sql.query("SELECT "+SocialService.ROOM+",(SELECT COUNT(*) FROM buddy_members m WHERE m.room_id=r.id) member_count FROM buddy_rooms r WHERE "+where+" ORDER BY r.created_at DESC,r.id LIMIT :limit OFFSET :offset",p);return ApiSupport.page(rows,page,size,total);}
    @PostMapping("/buddy/rooms")public ResponseEntity<?> createRoom(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/buddy/rooms",key,b,"RoomInput",201,()->service.createRoom(u,b));}
    @GetMapping("/buddy/rooms/{id}/members")public ResponseEntity<?> members(HttpServletRequest r,@PathVariable String id){return ApiSupport.response(service.members(auth.requireId(r),id),200);}
    @PostMapping("/buddy/rooms/{id}/join")public ResponseEntity<?> join(HttpServletRequest r,@PathVariable String id,@RequestHeader("Idempotency-Key")String key){String u=auth.requireId(r);return write(u,"POST","/buddy/rooms/"+id+"/join",key,Map.of(),null,200,()->service.join(u,id));}
    @PostMapping("/buddy/rooms/{id}/leave")public ResponseEntity<?> leave(HttpServletRequest r,@PathVariable String id,@RequestHeader("Idempotency-Key")String key){String u=auth.requireId(r);return write(u,"POST","/buddy/rooms/"+id+"/leave",key,Map.of(),null,200,()->service.leave(u,id));}
    @PostMapping("/buddy/rooms/{id}/close")public ResponseEntity<?> close(HttpServletRequest r,@PathVariable String id,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/buddy/rooms/"+id+"/close",key,b,"VersionInput",200,()->service.close(u,id,((Number)b.get("version")).intValue()));}
    @PostMapping("/buddy/rooms/{id}/invitations")public ResponseEntity<?> invite(HttpServletRequest r,@PathVariable String id,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/buddy/rooms/"+id+"/invitations",key,b,"InviteInput",201,()->service.invite(u,id,b.get("inviteeId").toString()));}
    @GetMapping("/buddy/invitations")public ResponseEntity<?> invites(HttpServletRequest r,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){String u=auth.requireId(r);SocialService.page(page,size);var p=map("u",u,"limit",size,"offset",(page-1)*size);long count=service.sql.db.queryForObject("SELECT COUNT(*) FROM buddy_invitations WHERE invitee_id=:u",p,Long.class);var rows=service.sql.query("SELECT "+SocialService.INVITE+" FROM buddy_invitations WHERE invitee_id=:u ORDER BY created_at DESC,id LIMIT :limit OFFSET :offset",p);for(var row:rows)if("PENDING".equals(row.get("state"))&&!Instant.parse(row.get("expiresAt").toString()).isAfter(Instant.now()))row.put("state","EXPIRED");return ApiSupport.page(rows,page,size,count);}
    @PatchMapping("/buddy/invitations/{id}")public ResponseEntity<?> inviteAction(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"PATCH","/buddy/invitations/"+id,null,b,"InviteAction",200,()->service.inviteAction(u,id,((Number)b.get("version")).intValue(),b.get("action").toString()));}
    @GetMapping("/buddy/rooms/{id}/tasks")public ResponseEntity<?> tasks(HttpServletRequest r,@PathVariable String id){return ApiSupport.response(service.tasks(auth.requireId(r),id),200);}
    @PostMapping("/buddy/rooms/{id}/tasks")public ResponseEntity<?> createTask(HttpServletRequest r,@PathVariable String id,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/buddy/rooms/"+id+"/tasks",key,b,"RoomTaskInput",201,()->service.createTask(u,id,b));}
    @PutMapping("/buddy/rooms/{id}/tasks/{taskId}/progress")public ResponseEntity<?> progress(HttpServletRequest r,@PathVariable String id,@PathVariable String taskId,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"PUT",r.getRequestURI(),null,b,"RoomTaskProgress",200,()->{service.progress(u,id,taskId,(Boolean)b.get("completed"));return map("accepted",true);});}
    @GetMapping("/buddy/candidates")public ResponseEntity<?> candidates(HttpServletRequest r,@RequestParam String q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){String u=auth.requireId(r);SocialService.page(page,size);if(q.length()<2||q.length()>40)throw SocialService.invalid("请填写2至40字搜索词。");var p=map("u",u,"q","%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%","limit",size,"offset",(page-1)*size);String where=" FROM users WHERE status='ACTIVE' AND buddy_discoverable=1 AND id<>:u AND (display_name LIKE :q ESCAPE '!' OR CAST(preferences AS CHAR) LIKE :q ESCAPE '!')";long total=service.sql.db.queryForObject("SELECT COUNT(*)"+where,p,Long.class);var rows=service.sql.query("SELECT id,display_name,preferences"+where+" ORDER BY id LIMIT :limit OFFSET :offset",p,Set.of("preferences"),Set.of());for(var row:rows){Object prefs=row.remove("preferences");Map<?,?> values=prefs instanceof Map<?,?> m?m:Map.of();row.put("roles",values.containsKey("roles")?values.get("roles"):List.of());row.put("cities",values.containsKey("cities")?values.get("cities"):List.of());}return ApiSupport.page(rows,page,size,total);}
    @GetMapping("/referrals")public ResponseEntity<?> referrals(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){SocialService.page(page,size);var p=map("limit",size,"offset",(page-1)*size);String from=" FROM referrals r JOIN users u ON u.id=r.provider_id WHERE r.status='PUBLISHED' AND r.expires_at>CURRENT_TIMESTAMP AND "+SocialService.ACTIVE_PROVIDER;long count=service.sql.db.queryForObject("SELECT COUNT(*)"+from,p,Long.class);return ApiSupport.page(service.sql.query("SELECT "+SocialService.REFERRAL+",1 provider_verified"+from+" ORDER BY r.created_at DESC,r.id LIMIT :limit OFFSET :offset",p,Set.of(),Set.of("provider_verified")),page,size,count);}
    @PostMapping("/referrals")public ResponseEntity<?> createReferral(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/referrals",key,b,"ReferralInput",201,()->service.createReferral(u,b));}
    @PostMapping("/referrals/{id}/requests")public ResponseEntity<?> request(HttpServletRequest r,@PathVariable String id,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"POST","/referrals/"+id+"/requests",key,b,"ReferralRequestInput",201,()->service.createRequest(u,id,b));}
    @GetMapping("/referral-requests")public ResponseEntity<?> requests(HttpServletRequest r,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String view){String u=auth.requireId(r);SocialService.page(page,size);if(view!=null&&!Set.of("APPLICANT","PROVIDER").contains(view))throw SocialService.invalid("申请查看身份无效。");var p=map("u",u,"limit",size,"offset",(page-1)*size);String where=view==null?"(q.applicant_id=:u OR r.provider_id=:u)":view.equals("APPLICANT")?"q.applicant_id=:u":"r.provider_id=:u";String from=" FROM referral_requests q JOIN referrals r ON r.id=q.referral_id WHERE "+where;long count=service.sql.db.queryForObject("SELECT COUNT(*)"+from,p,Long.class);return ApiSupport.page(service.sql.query("SELECT "+SocialService.REQUEST+from+" ORDER BY q.created_at DESC,q.id LIMIT :limit OFFSET :offset",p),page,size,count);}
    @PatchMapping("/referral-requests/{id}")public ResponseEntity<?> patchRequest(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){String u=auth.requireId(r);return write(u,"PATCH","/referral-requests/"+id,null,b,"ReferralRequestPatch",200,()->service.patchRequest(u,id,b));}
    @GetMapping("/radar/signals")public ResponseEntity<?> signals(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String companyId,@RequestParam(defaultValue="30")String days){SocialService.page(page,size);if(!Set.of("7","30").contains(days))throw SocialService.invalid("仅支持近7天或30天。");var p=map("from",Timestamp.from(Instant.now().minusSeconds(Long.parseLong(days)*86400)),"company",companyId);String where="FROM radar_signals WHERE status='PUBLISHED' AND occurred_at>=:from"+(companyId==null?"":" AND company_id=:company");return page(SocialService.BASE+",company_id,title,body,kind,source_url,occurred_at,verified_at,confidence,status",where,p,page,size,Set.of(),Set.of());}
}
